package app

import (
	"os"
	"strings"
)

// serverStep1 normalises one stage of the request pipeline. It trims the
// input, folds case and joins the parts with a separator so later stages
// can compare values without caring how the caller wrote them.
func serverStep1(parts []string) string {
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		out = append(out, strings.ToLower(strings.TrimSpace(p)))
	}
	return strings.Join(out, "/")
}

